query.base:
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
// Rate-limit / quota-exhaustion responses. RESOURCE_EXHAUSTED is the canonical status string; the
// LIKE clauses are defensive so provider-specific variants are not missed.
| EVAL is_throttled = attributes.response_code == "RESOURCE_EXHAUSTED"
      OR attributes.response_code LIKE "*RATE_LIMIT*"
      OR attributes.response_code LIKE "*QUOTA*"
      OR attributes.response_code LIKE "*TOO_MANY*"
// Read vs write path matters here: Google's guidance is that a bucket needs no managed ramp below
// roughly 5,000 reads/s or 1,000 writes/s, and above that should not double faster than every
// 20 minutes. Adjust the method lists if your estate uses methods not shown here.
| EVAL is_read  = attributes.method IN ("ReadObject", "GetObjectMetadata", "ListObjects", "GetBucketMetadata")
| EVAL is_write = attributes.method IN ("WriteObject", "DeleteObject")
// request_count is a ~60s delta counter stored as a gauge. SUM_OVER_TIME totals each series and SUM
// adds the series together: the collector can split one bucket's metric across several series
// (_metric_names_hash is a dimension), and each sample is still counted once. Never RATE() it.
| STATS total_requests     = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)),
        throttled_requests = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_throttled,
        read_requests      = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_read,
        write_requests     = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_write,
        throttled_codes    = VALUES(attributes.response_code) WHERE is_throttled,
        throttled_methods  = VALUES(attributes.method) WHERE is_throttled
    BY resource.attributes.bucket_name, resource.attributes.location
| EVAL throttled_requests = COALESCE(throttled_requests, 0)

breach.segment:
WHERE throttled_requests >= 5
// Approximate per-second rates. 1800 = timeWindowSize (30m) expressed in seconds — keep the two in
// sync if you change the window. Treat these as a lower bound: the collector polls Cloud Monitoring
// on an operator-configured interval and will not always retrieve every 60s sample.
| EVAL approx_read_requests_per_second  = ROUND(COALESCE(read_requests, 0)::DOUBLE / 1800.0, 2),
       approx_write_requests_per_second = ROUND(COALESCE(write_requests, 0)::DOUBLE / 1800.0, 2)
// Cast before dividing: request_count is a long and `a / b` would be integer division.
| EVAL throttled_pct = ROUND(throttled_requests::DOUBLE / total_requests * 100.0, 3)
// Throttling has a near-zero healthy baseline, so this share threshold is deliberately tiny.
// Remove this clause for zero-tolerance buckets; raise it if a workload is designed to be throttled.
| WHERE throttled_pct >= 0.05
| SORT throttled_requests DESC
| LIMIT 50
